import { Virtual } from 'swiper';
import { Swiper, SwiperSlide } from 'swiper/react';

import 'swiper/less';
import 'swiper/less/navigation';
import 'swiper/less/pagination';
import 'swiper/css/virtual';

export default function Swipe(props) {

  const slides = Array.from({ length: 1000 }).map(
    (el, index) => `Slide ${index + 1}`
  );

  return (
    <div className="portfolio__slider1">
    <div className="portfolio__slider1-title"></div>
    <div className="portfolio__slider1-slider">
    
   
    
   
    <Swiper modules={[Virtual]} spaceBetween={50} slidesPerView={4} virtual  navigation pagination={{ clickable: true }}>
    
    
      {props.slides.map((slideContent, index) =>(
        <SwiperSlide key={slideContent} virtualIndex={index}>
          {slideContent}
        </SwiperSlide>
      ))}
    </Swiper>
    ,/</div></div>
  );
};
